 "content": "def transform(grid):
    """Connect aligned cells of the rare marker color with 3s."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker_colors = [color for color, count in counts.items() if color != background]
    out = [row[:] for row in grid]

    for color in marker_colors:
        # Join consecutive markers in each row.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for left, right in zip(cols, cols[1:]):
                for c in range(left + 1, right):
                    out[r][c] = 3
        # Join consecutive markers in each column.
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for top, bottom in zip(rows, rows[1:]):
                for r in range(top + 1, bottom):
                    out[r][c] = 3
    return out
